(1619, '13700', 1503, 3435, 1, 3435, 11, 1, 94643.00, 0, 0, 0.00, 1, 1, '2026-01-16', '08:40:00', '10:05:00', '01:25', 'Se realizó revisión y limpieza de la máquina máquina, revisión y limpieza de chasis, validador, sensores, rodillos y prismas, módulo BNF y se verifica desgaste de piñones y rodillos, se hace una prueba de depósito exitosa, se valida comunicación con soporte, la máquina queda operativa sin fallas.', NULL, 0, NULL, '2026-01-17 13:42:31', 1, NULL),
(1620, '13701', 1503, 1978, 1, 1978, 11, 1, 94643.00, 0, 0, 0.00, 1, 1, '2026-01-16', '10:34:00', '11:15:00', '00:41', 'Se realizó revisión y limpieza de la máquina, validador, sensores, prismas, módulo BNF, rodillos, se realiza revisión de chasis y conexiones, se hace prueba de depósito exitosa, se valida comunicación con soporte máquina queda operativa sin novedad', NULL, 0, NULL, '2026-01-17 13:48:05', 1, NULL),
